def _prepare_image_for_reportlab(self, img) -> Optional[io.BytesIO]:
    """Converts any image source (numpy, PIL, stream) to a BytesIO PNG stream for ReportLab."""
    if img is None:
        return None

    try:
        if isinstance(img, (str, Path)):
            if os.path.exists(str(img)):
                return str(img)
            return None

        buf = io.BytesIO()
        if isinstance(img, np.ndarray):
            # Standardize BGR/BGRA to RGB/RGBA for PIL
            if len(img.shape) == 3:
                if img.shape[2] == 4:
                    img_to_save = cv.cvtColor(img, cv.COLOR_BGRA2RGBA)
                else:
                    img_to_save = cv.cvtColor(img, cv.COLOR_BGR2RGB)
            else:
                img_to_save = img # Grayscale

            pil_img = PILImage.fromarray(img_to_save)
            pil_img.save(buf, format='PNG')
        elif isinstance(img, PILImage.Image):
            img.save(buf, format='PNG')
        elif isinstance(img, (io.BytesIO, bytes)):
            # If it's already bytes/stream, return it seeked to 0
            if isinstance(img, bytes):
                buf.write(img)
            else:
                img.seek(0)
                return img
        else:
            return None

        buf.seek(0)
        return buf
    except Exception as e:
        logger.warning(f"Failed to prepare image for report: {e}")
        return None

def _ensure_numpy_array(self, data) -> Optional[np.ndarray]:
    """Converts various image sources (BytesIO, bytes, numpy) to a BGR numpy array."""
    if data is None:
        return None
    if isinstance(data, np.ndarray):
        return data

    try:
        if hasattr(data, 'read'): # Stream
            data.seek(0)
            content = data.read()
            data.seek(0) # CRITICAL: Reset stream for next consumer (the report builder)
        elif isinstance(data, (bytes, bytearray)):
            content = data
        elif isinstance(data, (str, Path)) and os.path.exists(str(data)):
            return cv.imread(str(data))
        else:
            return None

        nparr = np.frombuffer(content, np.uint8)
        img = cv.imdecode(nparr, cv.IMREAD_UNCHANGED)
        return img
    except Exception as e:
        logger.warning(f"Could not convert data to numpy array: {e}")
        return None

